pub(crate) struct DoctorRuntimeSummaryInput<'a> {
    pub(crate) surface: &'static str,
    pub(crate) state: &'a serde_json::Value,
    pub(crate) status: &'a str,
    pub(crate) healthy: bool,
    pub(crate) initialized: bool,
    pub(crate) db_exists: bool,
    pub(crate) rebuild_active: bool,
    pub(crate) coverage_risk: &'a DoctorCoverageRiskSummary,
    pub(crate) coverage_source: &'static str,
    pub(crate) coverage_checked: bool,
    pub(crate) quarantine_summary: Option<&'a DiagQuarantineSummary>,
    pub(crate) recommended_action: Option<&'a String>,
    pub(crate) data_dir: &'a Path,
}

pub(crate) fn doctor_summary_coverage_state(
    coverage_risk: &DoctorCoverageRiskSummary,
) -> &'static str {
    match coverage_risk.status.as_str() {
        "ok" => "ok",
        "not_initialized" => "not_initialized",
        "sole_copy_risk" => "sole_copy_risk",
        "raw_mirror_backfill_available" => "raw_mirror_backfill_available",
        "raw_mirror_capture_disabled" => "raw_mirror_capture_disabled",
        "raw_mirror_unlinked" => "raw_mirror_unlinked",
        "current_sources_newer_than_archive" => "current_sources_newer_than_archive",
        status if status.starts_with("unchecked") => "not_checked",
        _ => "unknown",
    }
}

pub(crate) fn doctor_summary_source_mirror_state(
    coverage_risk: &DoctorCoverageRiskSummary,
) -> &'static str {
    if coverage_risk.status == "not_initialized" {
        "not_initialized"
    } else if coverage_risk.confidence_tier == "unchecked" {
        "not_checked"
    } else if coverage_risk.db_without_raw_mirror_count > 0 {
        "archive_rows_without_raw_mirror"
    } else if coverage_risk.mirror_without_db_link_count > 0 {
        "raw_mirror_unlinked"
    } else if coverage_risk.raw_mirror_db_link_count > 0 {
        "linked"
    } else if coverage_risk.archive_conversation_count > 0 {
        "missing"
    } else {
        "empty"
    }
}

/// Archive rows lacking a raw copy that doctor could still capture. With
/// capture switched off (GH #506) they are the operator's choice, reported as
/// low risk rather than as a coverage gap.
pub(crate) fn doctor_unmirrored_rows_are_a_gap(coverage_risk: &DoctorCoverageRiskSummary) -> bool {
    coverage_risk.db_without_raw_mirror_count > 0 && !coverage_risk.raw_mirror_capture_disabled
}

pub(crate) fn doctor_summary_risk_level(coverage_risk: &DoctorCoverageRiskSummary) -> &'static str {
    if coverage_risk.status == "sole_copy_risk" {
        "high"
    } else if coverage_risk.confidence_tier == "unchecked" {
        "unknown"
    } else if coverage_risk.missing_current_source_count > 0
        || doctor_unmirrored_rows_are_a_gap(coverage_risk)
        || coverage_risk.db_projection_only_count > 0
    {
        "medium"
    } else if coverage_risk.mirror_without_db_link_count > 0
        || coverage_risk.current_source_newer_than_archive_count > 0
        || coverage_risk.db_without_raw_mirror_count > 0
    {
        "low"
    } else {
        "none"
    }
}

pub(crate) fn doctor_summary_health_class(
    coverage_risk: &DoctorCoverageRiskSummary,
    repair_blocked_reason: Option<&str>,
    healthy: bool,
) -> &'static str {
    if repair_blocked_reason.is_some() {
        "repair-blocked"
    } else if coverage_risk.status == "sole_copy_risk"
        || coverage_risk.missing_current_source_count > 0
        || doctor_unmirrored_rows_are_a_gap(coverage_risk)
        || coverage_risk.db_projection_only_count > 0
    {
        "degraded-archive-risk"
    } else if healthy {
        "healthy"
    } else {
        "degraded-derived-assets"
    }
}

pub(crate) fn doctor_summary_failure_marker_path(data_dir: &Path) -> Option<String> {
    ["repair_apply", "cleanup_apply", "restore_apply"]
        .into_iter()
        .map(|repair_class| collect_doctor_repair_failure_marker(data_dir, repair_class))
        .find(|marker| marker.found)
        .and_then(|marker| marker.path)
}

pub(crate) fn build_doctor_runtime_summary(
    input: DoctorRuntimeSummaryInput<'_>,
) -> serde_json::Value {
    let fallback_mode = doctor_fallback_mode_from_state(input.state);
    let doctor_lock = doctor_probe_mutation_lock(input.data_dir);
    let active_doctor_repair = matches!(
        doctor_lock,
        DoctorMutationLockObservation::Active { .. }
            | DoctorMutationLockObservation::Unavailable { .. }
    );
    let active_index_maintenance = input
        .state
        .pointer("/rebuild/active")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(input.rebuild_active);
    let repair_blocked_reason = if active_doctor_repair {
        Some("another doctor repair appears to hold the mutation lock".to_string())
    } else if active_index_maintenance {
        Some("index maintenance is active; mutating doctor repair should wait".to_string())
    } else {
        None
    };
    let failure_marker_path = doctor_summary_failure_marker_path(input.data_dir);
    let repair_previously_failed = failure_marker_path.is_some();
    let coverage_state = doctor_summary_coverage_state(input.coverage_risk);
    let source_mirror_state = doctor_summary_source_mirror_state(input.coverage_risk);
    let risk_level = doctor_summary_risk_level(input.coverage_risk);
    let health_class = doctor_summary_health_class(
        input.coverage_risk,
        repair_blocked_reason.as_deref(),
        input.healthy,
    );
    let archive_initialized = input.initialized && input.db_exists;
    let doctor_check_recommended = repair_blocked_reason.is_some()
        || repair_previously_failed
        || (archive_initialized
            && (!input.coverage_checked
                || !matches!(
                    input.coverage_risk.status.as_str(),
                    "ok" | "not_initialized"
                )));
    let repair_recommended = input.coverage_risk.recommended_action != "none"
        && input.coverage_risk.confidence_tier != "unchecked";
    let recommended_action = if let Some(reason) = repair_blocked_reason.as_ref() {
        if reason.contains("index maintenance") {
            "Wait for the active index operation to finish, then run 'cass doctor check --json'."
                .to_string()
        } else {
            "Wait for the active doctor owner to finish, then run 'cass doctor check --json'."
                .to_string()
        }
    } else if doctor_check_recommended {
        "Run 'cass doctor check --json' to refresh archive coverage and repair readiness."
            .to_string()
    } else {
        input
            .recommended_action
            .cloned()
            .unwrap_or_else(|| "none".to_string())
    };
    let blocked_reasons = repair_blocked_reason
        .as_ref()
        .map(|reason| vec![reason.clone()])
        .unwrap_or_default();
    let cleanup_reclaimable_bytes = input
        .quarantine_summary
        .map(|summary| summary.cleanup_dry_run_reclaimable_bytes);
    let quarantine_summary = input
        .quarantine_summary
        .and_then(|summary| serde_json::to_value(summary).ok())
        .unwrap_or(serde_json::Value::Null);
    let coverage_known =
        input.coverage_checked && input.coverage_risk.confidence_tier != "unchecked";
    let coverage_delta = serde_json::json!({
        "status": if coverage_known { "unchanged" } else { "unknown" },
        "archive_conversation_count": coverage_known.then_some(input.coverage_risk.archive_conversation_count),
        "visible_source_conversation_count": coverage_known.then_some(
            input
                .coverage_risk
                .archive_conversation_count
                .saturating_sub(input.coverage_risk.missing_current_source_count)
        ),
        "raw_mirror_manifest_count": serde_json::Value::Null,
        "db_projection_only_count": coverage_known.then_some(input.coverage_risk.db_projection_only_count),
        "missing_current_source_count": coverage_known.then_some(input.coverage_risk.missing_current_source_count),
        "conversation_delta": serde_json::Value::Null,
        "message_delta": serde_json::Value::Null,
        "semantic_vector_delta": serde_json::Value::Null,
        "derived_asset_delta": serde_json::Value::Null,
    });
    let outcome_kind = if repair_blocked_reason.is_some() {
        "blocked"
    } else {
        "no_op"
    };
    let status = if repair_blocked_reason.is_some() {
        "blocked"
    } else if !input.initialized || !input.coverage_checked {
        "skipped"
    } else if matches!(risk_level, "high" | "medium" | "low") {
        "warn"
    } else {
        "ok"
    };
    let operator_action_needed = input
        .recommended_action
        .as_ref()
        .is_some_and(|action| action.as_str() != "none");
    let next_command = if doctor_check_recommended || repair_blocked_reason.is_some() {
        serde_json::json!("cass doctor check --json")
    } else if !archive_initialized {
        serde_json::json!("cass index --full")
    } else {
        serde_json::Value::Null
    };
    let operation_outcome_kind = if repair_blocked_reason.is_some() {
        "repair-blocked"
    } else if doctor_check_recommended || operator_action_needed {
        "ok-read-only-diagnosed"
    } else {
        "ok-no-action-needed"
    };

    serde_json::json!({
        "schema_version": 2,
        "surface": input.surface,
        "mode": "read-only-check",
        "status": status,
        "outcome_kind": outcome_kind,
        "health_class": health_class,
        "risk_level": risk_level,
        "asset_class": "canonical_archive_db",
        "fallback_mode": fallback_mode,
        "authority_status": "read_only",
        "coverage_delta": coverage_delta,
        "blocked_reasons": blocked_reasons,
        "plan_fingerprint": serde_json::Value::Null,
        "receipt_path": serde_json::Value::Null,
        "event_log_path": serde_json::Value::Null,
        "artifact_manifest_path": serde_json::Value::Null,
        "recommended_action": recommended_action,
        "redaction_status": "redacted",
        "contract_provenance": "runtime",
        "operation_outcome": {
            "kind": operation_outcome_kind,
            "reason": if repair_blocked_reason.is_some() {
                "repair readiness is blocked by active work"
            } else if !archive_initialized {
                "archive database is not initialized yet, so doctor coverage cannot be checked"
            } else if doctor_check_recommended {
                "health/status used bounded readiness evidence and recommends doctor check for full archive coverage"
            } else {
                "health/status summary found no repair blocker in bounded evidence"
            },
            "action_taken": "reported bounded health/status doctor summary without mutating archive data",
            "action_not_taken": "did not run deep doctor collectors, source sync, rebuild, model verification, or filesystem-wide repair work",
            "safe_to_retry": repair_blocked_reason.is_none(),
            "requires_override": false,
            "data_loss_risk": risk_level,
            "next_command": next_command,
            "artifact_manifest_path": serde_json::Value::Null,
            "exit_code_kind": if repair_blocked_reason.is_some() { "lock-busy" } else { "success" },
        },
        "doctor_available": true,
        "safe_auto_run_eligible": false,
        "last_receipt_path": serde_json::Value::Null,
        "failure_marker_path": failure_marker_path,
        "repair_previously_failed": repair_previously_failed,
        "active_repair": {
            "active": active_doctor_repair,
            "active_index_maintenance": active_index_maintenance,
            "repair_blocked_reason": repair_blocked_reason,
        },
        "repair_recommended": repair_recommended,
        "repair_blocked_reason": repair_blocked_reason,
        "doctor_check_recommended": doctor_check_recommended,
        "archive_coverage_state": coverage_state,
        "source_mirror_state": source_mirror_state,
        "sole_copy_conversation_count": input.coverage_risk.sole_copy_warning_count,
        "cleanup_reclaimable_bytes": cleanup_reclaimable_bytes,
        "quarantine_summary": quarantine_summary,
        "coverage_source": {
            "status": if input.coverage_checked { "checked" } else { "not_checked" },
            "source": input.coverage_source,
            "confidence_tier": input.coverage_risk.confidence_tier,
            "generated_at": input
                .state
                .pointer("/_meta/timestamp")
                .and_then(serde_json::Value::as_str),
            "stale_after_seconds": if input.coverage_checked { 300 } else { 0 },
            "source_report_id": serde_json::Value::Null,
            "recommended_action": if input.coverage_checked {
                "Use this bounded status summary for routing; run cass doctor check --json before mutating."
            } else if !archive_initialized {
                "Run cass index --full once before archive coverage can be assessed."
            } else {
                "Run cass doctor check --json for current archive coverage; health/status did not run deep collectors."
            },
        },
        "health_status": input.status,
        "db_exists": input.db_exists,
    })
}

pub(crate) fn doctor_raw_mirror_summary_checksum_status(
    raw_mirror: &DoctorRawMirrorReport,
) -> DoctorArtifactChecksumStatus {
    if raw_mirror.summary.missing_blob_count > 0 {
        DoctorArtifactChecksumStatus::Missing
    } else if raw_mirror.summary.checksum_mismatch_count > 0
        || raw_mirror.summary.manifest_checksum_mismatch_count > 0
        || raw_mirror.summary.invalid_manifest_count > 0
    {
        DoctorArtifactChecksumStatus::Mismatched
    } else if raw_mirror.summary.verified_blob_count > 0
        && raw_mirror.summary.manifest_checksum_not_recorded_count == 0
    {
        DoctorArtifactChecksumStatus::Matched
    } else {
        DoctorArtifactChecksumStatus::NotRecorded
    }
}

pub(crate) fn doctor_source_authority_candidate(
    authority: DoctorSourceAuthorityKind,
    decision: DoctorSourceAuthorityDecision,
    reason: String,
    coverage_delta: i64,
    freshness_delta_ms: Option<i64>,
    checksum_status: DoctorArtifactChecksumStatus,
    evidence: Vec<String>,
) -> DoctorSourceAuthorityCandidate {
    let policy = doctor_source_authority_policy(authority);
    DoctorSourceAuthorityCandidate {
        authority,
        decision,
        reason,
        repairs: policy.repairs.to_vec(),
        coverage_delta,
        freshness_delta_ms,
        checksum_status,
        evidence,
    }
}

pub(crate) fn doctor_source_authority_checksum_evidence(
    raw_mirror: &DoctorRawMirrorReport,
) -> DoctorSourceAuthorityChecksumEvidence {
    DoctorSourceAuthorityChecksumEvidence {
        raw_mirror_status: raw_mirror.status.clone(),
        raw_mirror_manifest_count: raw_mirror.summary.manifest_count,
        raw_mirror_verified_blob_count: raw_mirror.summary.verified_blob_count,
        raw_mirror_missing_blob_count: raw_mirror.summary.missing_blob_count,
        raw_mirror_checksum_mismatch_count: raw_mirror.summary.checksum_mismatch_count,
        raw_mirror_manifest_checksum_mismatch_count: raw_mirror
            .summary
            .manifest_checksum_mismatch_count,
        raw_mirror_manifest_checksum_not_recorded_count: raw_mirror
            .summary
            .manifest_checksum_not_recorded_count,
        raw_mirror_invalid_manifest_count: raw_mirror.summary.invalid_manifest_count,
        summary_status: doctor_raw_mirror_summary_checksum_status(raw_mirror),
    }
}

pub(crate) fn doctor_source_authority_coverage_delta(
    source_inventory: &DoctorSourceInventoryReport,
    raw_mirror: &DoctorRawMirrorReport,
) -> DoctorSourceAuthorityCoverageDelta {
    let visible_local_source_conversation_count = source_inventory
        .local_source_count
        .saturating_sub(source_inventory.missing_current_source_count);
    let raw_mirror_db_link_count = raw_mirror
        .manifests
        .iter()
        .filter(|manifest| {
            manifest.status == "verified"
                && manifest.blob_checksum_status == DoctorArtifactChecksumStatus::Matched
                && manifest.manifest_checksum_status == DoctorArtifactChecksumStatus::Matched
        })
        .map(|manifest| manifest.db_link_count)
        .sum::<usize>();
    DoctorSourceAuthorityCoverageDelta {
        archive_conversation_count: source_inventory.total_indexed_conversations,
        visible_local_source_conversation_count,
        missing_current_source_count: source_inventory.missing_current_source_count,
        remote_source_count: source_inventory.remote_source_count,
        unknown_mapping_count: source_inventory.unknown_mapping_count,
        raw_mirror_db_link_count,
        visible_local_source_minus_archive: visible_local_source_conversation_count as i64
            - source_inventory.total_indexed_conversations as i64,
        raw_mirror_links_minus_archive: raw_mirror_db_link_count as i64
            - source_inventory.total_indexed_conversations as i64,
    }
}

pub(crate) fn doctor_source_authority_freshness_delta(
    db_path: &Path,
    raw_mirror: &DoctorRawMirrorReport,
) -> DoctorSourceAuthorityFreshnessDelta {
    let archive_db_modified_at_ms = std::fs::metadata(db_path)
        .ok()
        .and_then(|metadata| metadata.modified().ok())
        .and_then(system_time_to_unix_ms);
    let newest_raw_mirror_capture_at_ms =
        raw_mirror.manifests.iter().map(|m| m.captured_at_ms).max();
    let newest_raw_mirror_source_mtime_ms = raw_mirror
        .manifests
        .iter()
        .filter_map(|manifest| manifest.source_mtime_ms)
        .max();
    let raw_mirror_capture_minus_archive_db_ms =
        match (newest_raw_mirror_capture_at_ms, archive_db_modified_at_ms) {
            (Some(raw), Some(db)) => Some(raw.saturating_sub(db)),
            _ => None,
        };
    let freshness_state = if archive_db_modified_at_ms.is_none() {
        "archive-db-missing".to_string()
    } else if raw_mirror_capture_minus_archive_db_ms.is_some_and(|delta| delta > 0) {
        "raw-mirror-newer-than-archive-db".to_string()
    } else {
        "archive-db-current-or-not-compared".to_string()
    };
    DoctorSourceAuthorityFreshnessDelta {
        archive_db_modified_at_ms,
        newest_raw_mirror_capture_at_ms,
        newest_raw_mirror_source_mtime_ms,
        raw_mirror_capture_minus_archive_db_ms,
        freshness_state,
    }
}

pub(crate) fn build_doctor_source_authority_report(
    db_path: &Path,
    source_inventory: &DoctorSourceInventoryReport,
    raw_mirror: &DoctorRawMirrorReport,
) -> DoctorSourceAuthorityReport {
    let coverage_delta = doctor_source_authority_coverage_delta(source_inventory, raw_mirror);
    let freshness_delta = doctor_source_authority_freshness_delta(db_path, raw_mirror);
    let checksum_evidence = doctor_source_authority_checksum_evidence(raw_mirror);
    // Trust the mirror as a repair authority on its *blob integrity*, not the
    // aggregate `status` string. `status` degrades to "warn" for non-integrity
    // reasons too — stale `interrupted_capture` tmp debris and size warnings —
    // which wrongly refused a mirror with 0 missing / 0 mismatched blobs as a
    // reconstruction authority (#374 Issue 1). This is a strict relaxation:
    // every mirror the old `status == "verified"` gate accepted had all these
    // integrity counts at 0 too, so nothing previously refused for a real
    // integrity fault becomes trusted. Unrecorded checksums stay disqualifying
    // (we can't confirm those blobs).
    let raw_mirror_integrity_verified = raw_mirror.summary.manifest_count > 0
        && raw_mirror.summary.invalid_manifest_count == 0
        && raw_mirror.summary.missing_blob_count == 0
        && raw_mirror.summary.checksum_mismatch_count == 0
        && raw_mirror.summary.manifest_checksum_mismatch_count == 0
        && raw_mirror.summary.manifest_checksum_not_recorded_count == 0;
    let raw_mirror_trusted = raw_mirror_integrity_verified
        && checksum_evidence.summary_status == DoctorArtifactChecksumStatus::Matched;
    let archive_available = source_inventory.db_available;
    let mut selected_authorities = Vec::new();
    let mut rejected_authorities = Vec::new();

    if archive_available {
        selected_authorities.push(doctor_source_authority_candidate(
            DoctorSourceAuthorityKind::CanonicalArchiveDb,
            DoctorSourceAuthorityDecision::ReadOnly,
            format!(
                "archive database currently contains {} indexed conversation(s) and is authoritative for derived rebuild decisions",
                source_inventory.total_indexed_conversations
            ),
            0,
            None,
            DoctorArtifactChecksumStatus::NotRecorded,
            vec![
                "archive-db-opened".to_string(),
                format!(
                    "archive-conversation-count={}",
                    source_inventory.total_indexed_conversations
                ),
            ],
        ));
    }

    if raw_mirror_trusted {
        let reason = if source_inventory.missing_current_source_count > 0 {
            format!(
                "verified raw mirror evidence remains available while {} indexed local conversation(s) have missing upstream files",
                source_inventory.missing_current_source_count
            )
        } else {
            "verified raw mirror evidence can seed reconstruction candidates when later repair modes need it".to_string()
        };
        selected_authorities.push(doctor_source_authority_candidate(
            DoctorSourceAuthorityKind::VerifiedRawMirror,
            DoctorSourceAuthorityDecision::CandidateOnly,
            reason,
            coverage_delta.raw_mirror_links_minus_archive,
            freshness_delta.raw_mirror_capture_minus_archive_db_ms,
            checksum_evidence.summary_status,
            vec![
                format!(
                    "verified-blob-count={}",
                    raw_mirror.summary.verified_blob_count
                ),
                format!("db-link-count={}", coverage_delta.raw_mirror_db_link_count),
            ],
        ));
    } else {
        rejected_authorities.push(doctor_source_authority_candidate(
            DoctorSourceAuthorityKind::VerifiedRawMirror,
            DoctorSourceAuthorityDecision::Refused,
            format!(
                "raw mirror is not trusted for archive repair: status={}, checksum_status={}",
                raw_mirror.status,
                doctor_artifact_checksum_status_label(checksum_evidence.summary_status)
            ),
            coverage_delta.raw_mirror_links_minus_archive,
            freshness_delta.raw_mirror_capture_minus_archive_db_ms,
            checksum_evidence.summary_status,
            vec![
                format!("manifest-count={}", raw_mirror.summary.manifest_count),
                format!(
                    "missing-blob-count={}",
                    raw_mirror.summary.missing_blob_count
                ),
                format!(
                    "checksum-mismatch-count={}",
                    raw_mirror.summary.checksum_mismatch_count
                        + raw_mirror.summary.manifest_checksum_mismatch_count
                ),
            ],
        ));
    }

    if source_inventory.missing_current_source_count > 0
        || source_inventory.unknown_mapping_count > 0
    {
        rejected_authorities.push(doctor_source_authority_candidate(
            DoctorSourceAuthorityKind::LiveUpstreamSource,
            DoctorSourceAuthorityDecision::Refused,
            format!(
                "live upstream source coverage is incomplete: {} missing local conversation(s), {} unknown mapping(s)",
                source_inventory.missing_current_source_count,
                source_inventory.unknown_mapping_count
            ),
            coverage_delta.visible_local_source_minus_archive,
            None,
            DoctorArtifactChecksumStatus::NotRecorded,
            vec![
                "coverage-shrinks-relative-to-archive".to_string(),
                "provider-pruning-risk".to_string(),
            ],
        ));
    }

    if source_inventory.remote_source_count > 0 {
        rejected_authorities.push(doctor_source_authority_candidate(
            DoctorSourceAuthorityKind::RemoteSyncCopy,
            DoctorSourceAuthorityDecision::Refused,
            format!(
                "{} remote conversation row(s) require matched source identity, matched origin host, verified generation/checksum evidence, and non-decreasing coverage before repair authority",
                source_inventory.remote_source_count
            ),
            0,
            None,
            DoctorArtifactChecksumStatus::NotRecorded,
            vec![
                "remote-identity-ambiguous".to_string(),
                "remote-generation-unverified".to_string(),
                "remote-copy-coverage-unknown".to_string(),
            ],
        ));
    }

    for authority in [
        DoctorSourceAuthorityKind::VerifiedBackupBundle,
        DoctorSourceAuthorityKind::VerifiedCandidateArchive,
        DoctorSourceAuthorityKind::DerivedLexicalIndex,
        DoctorSourceAuthorityKind::DerivedSemanticIndex,
        DoctorSourceAuthorityKind::SupportBundle,
    ] {
        let policy = doctor_source_authority_policy(authority);
        rejected_authorities.push(doctor_source_authority_candidate(
            authority,
            DoctorSourceAuthorityDecision::Refused,
            policy.refuses_when.join("; "),
            0,
            None,
            DoctorArtifactChecksumStatus::NotRecorded,
            policy
                .refuses_when
                .iter()
                .map(|reason| reason.to_string())
                .collect(),
        ));
    }

    let selected_authority = selected_authorities
        .first()
        .map(|candidate| candidate.authority);
    let decision = selected_authorities
        .first()
        .map(|candidate| candidate.decision)
        .unwrap_or(DoctorSourceAuthorityDecision::Refused);

    DoctorSourceAuthorityReport {
        schema_version: 1,
        decision,
        selected_authority,
        selected_authorities,
        rejected_authorities,
        coverage_delta,
        freshness_delta,
        checksum_evidence,
        matrix: doctor_source_authority_matrix_report(),
        notes: vec![
            "Doctor chooses the most conservative authority first; live sources never outrank an existing archive when coverage shrinks.".to_string(),
            "Candidate-only means evidence may seed an isolated rebuild candidate, not direct promotion.".to_string(),
            "Promotion requires a later non-decreasing coverage check plus checksum-verified receipt.".to_string(),
        ],
    }
}

pub(crate) fn doctor_refuse_source_authority_when_collectors_deferred(
    mut report: DoctorSourceAuthorityReport,
    reason: &str,
    preserve_verified_raw_mirror_candidate: bool,
) -> DoctorSourceAuthorityReport {
    let mut preserved_authorities = Vec::new();
    for mut candidate in std::mem::take(&mut report.selected_authorities) {
        if preserve_verified_raw_mirror_candidate
            && matches!(
                candidate.authority,
                DoctorSourceAuthorityKind::VerifiedRawMirror
            )
            && matches!(
                candidate.decision,
                DoctorSourceAuthorityDecision::CandidateOnly
            )
            && matches!(
                candidate.checksum_status,
                DoctorArtifactChecksumStatus::Matched
            )
        {
            candidate.reason = format!(
                "checksum-verified raw mirror may seed an isolated candidate after affirmative canonical corruption; archive-wide coverage remains unchecked: {reason}"
            );
            candidate
                .evidence
                .push("affirmative-canonical-integrity-failure".to_string());
            candidate
                .evidence
                .push("candidate-only-not-promotion-authority".to_string());
            preserved_authorities.push(candidate);
            continue;
        }
        candidate.decision = DoctorSourceAuthorityDecision::Refused;
        candidate.reason = format!(
            "archive-wide authority evidence is unchecked; prior provisional selection refused: {reason}"
        );
        candidate
            .evidence
            .push("archive-wide-collectors-deferred".to_string());
        report.rejected_authorities.push(candidate);
    }
    report.selected_authorities = preserved_authorities;
    report.selected_authority = report
        .selected_authorities
        .first()
        .map(|candidate| candidate.authority);
    report.decision = match report.selected_authorities.first() {
        Some(candidate) => candidate.decision,
        None => DoctorSourceAuthorityDecision::Refused,
    };
    report.notes.push(reason.to_string());
    if report.selected_authorities.is_empty() {
        report.notes.push(
            "No zero-valued deferred coverage field may select or promote a repair authority."
                .to_string(),
        );
    } else {
        report.notes.push(
            "Affirmative canonical corruption permits checksum-verified raw-mirror CandidateOnly authority for isolated reconstruction; deferred coverage fields still cannot authorize promotion."
                .to_string(),
        );
    }
    report
}

pub(crate) const DOCTOR_CANDIDATE_SCHEMA_VERSION: u32 = 1;

pub(crate) const DOCTOR_CANDIDATE_MANIFEST_KIND: &str = "cass_doctor_reconstruct_candidate_v1";
